const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var startDate = '2016-08-01';
  var endDate = '2018-02-28';

  // Get Cambodia boundary
  var cambodia = ee.FeatureCollection('FAO/GAUL/2015/level0')
    .filter(ee.Filter.eq('ADM0_NAME', 'Cambodia'));

  // Get bounds and split into north/south
  var bounds = cambodia.geometry().bounds();
  var coords = bounds.coordinates().get(0);
  var minLon = coords.get(0).get(0);
  var maxLon = coords.get(2).get(0);
  var minLat = coords.get(0).get(1);
  var maxLat = coords.get(1).get(1);
  var midLat = (minLat + maxLat) / 2;

  // Create north and south regions
  var northRegion = ee.Geometry.Rectangle([minLon, midLat, maxLon, maxLat]);
  var southRegion = ee.Geometry.Rectangle([minLon, minLat, maxLon, midLat]);

  // Clip to Cambodia
  northRegion = northRegion.intersection(cambodia.geometry());
  southRegion = southRegion.intersection(cambodia.geometry());

  // 2. Data Acquisition - MODIS Active Fires
  var fires = ee.FeatureCollection('MODIS/006/MCD14ML')
    .filter(ee.Filter.date(startDate, endDate))
    .filter(ee.Filter.bounds(cambodia.geometry()));

  var fireCount = fires.size().getInfo();
  console.log('Total fire detections in Cambodia:', fireCount);

  // Check if collection is empty
  if (fireCount === 0) {
    console.log('No fire detections found in date range.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Count fires in each region
  var northFires = fires.filterBounds(northRegion);
  var southFires = fires.filterBounds(southRegion);

  var northCount = northFires.size().getInfo();
  var southCount = southFires.size().getInfo();

  console.log('North Cambodia fires:', northCount);
  console.log('South Cambodia fires:', southCount);
  console.log('North area (approx):', northRegion.area().divide(1e6).getInfo().toFixed(1), 'km²');
  console.log('South area (approx):', southRegion.area().divide(1e6).getInfo().toFixed(1), 'km²');

  // 4. Validation & Final Answer
  if (typeof northCount !== 'number' || typeof southCount !== 'number' || 
      isNaN(northCount) || isNaN(southCount)) {
    console.log('Invalid count values.');
    console.log('<answer>C3</answer>');
  } else if (northCount > southCount) {
    console.log('North has more fire detections.');
    console.log('<answer>A</answer>');
  } else {
    console.log('South has equal or more fire detections.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
